        row_tiles = (M + rows_per_cta - 1) // rows_per_cta
        # Fine-grained split-K work partitioning: the profiler shows a large
        # partial-wave tail (3072 CTAs -> the last wave runs mostly idle).
        # B stays fully L2-resident (4MB << 72MB, evict_last policy) and A
        # is streamed exactly once (evict_first), so extra splits add no
        # DRAM traffic. Oversubscribing the SMs with many small equal-cost
        # CTAs shrinks the tail quantization from one huge K/3 slice to one
      # tiny work item (~K/24), while keeping all v4 slices 16B-aligned.
        target_blocks = 24576
        nsplit = (target_blocks + row_tiles - 1) // row_tiles
        nsplit = max(1, min(nsplit, K // 4096))
        slice_len = ((K // nsplit) // 4) * 4 if nsplit > 1 else K
        module.launch(
            "matvec_f32",
            grid=(nsplit, row_tiles, 1),
            block=(128, 1, 1),
            arguments=[A, B, C, u32(M), u32(K), u32(slice_len), u32(nsplit)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C
